import { navigationHTML, menuGridHTML, pageIds } from './navigation.js';
import { createMarketingUI } from './marketing.js';
import { getLanguage, locale, setLanguage, localize, observeLanguage, languagePicker, translate } from './i18n.js';
import { createSmartTools } from './assistant.js';
export function mountStudio(root,options={}){
const lifetime=new AbortController();let disposed=false,pendingRoute=options.initialView||'calendar';
root.innerHTML='<div class="initial-loading">Menyiapkan workspace Vayora…</div>';

const $=selector=>root.querySelector('#vs-detail[open]')?.querySelector(selector)||root.querySelector(selector),$$=selector=>[...root.querySelectorAll(selector)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const button=(text,action,kind='',ico='',extra='')=>`<button type="button" class="vs-button ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const icons=()=>globalThis.lucide?.createIcons({attrs:{width:17,height:17}});
const names={draft:'Draft',review:'Perlu diperiksa',ready:'Siap tayang',scheduled:'Terjadwal',processing:'Memproses',published:'Terbit',failed:'Gagal',uncertain:'Periksa hasil'};
const categories=['Operasional','Reservasi','Laporan owner','Website booking','Demo produk'];
const goals=['Pengenalan brand','Edukasi fitur','Permintaan demo'];
let csrf='',user=null,workspace=null,draft=null,dirty=false,busy=false,slide=0,confirmation=null,importGroups=[],inviteToken='',authMode='login';
const state={view:'calendar',mode:'week',anchor:today(),day:null,selected:null,format:'Semua',status:'Semua',goal:'Semua',history:'Semua',importStep:1,modal:null,detailMode:'summary',search:'',quick:'all',sort:'newest',versions:[],versionId:''};
function today(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(type=>parts.find(x=>x.type===type).value).join('-');}
const dateObj=s=>new Date(s+'T00:00:00Z');
function addDays(s,n){const d=dateObj(s);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function monday(s){const d=dateObj(s);return addDays(s,-((d.getUTCDay()+6)%7));}
const nice=s=>s?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',timeZone:'UTC'}).format(dateObj(s)):'';
const fullDate=s=>new Intl.DateTimeFormat(locale(),{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(dateObj(s));
const stamp=s=>new Intl.DateTimeFormat(locale(),{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(s))+' WIB';
const clone=x=>JSON.parse(JSON.stringify(x));
const current=()=>workspace?.posts.find(x=>x.id===state.selected)||workspace?.posts[0];
const count=status=>workspace.posts.filter(x=>x.status===status).length;
const badge=item=>`<span class="vs-status ${item.status==='uncertain'?'failed':item.status}">${esc(names[item.status])}</span>`;
async function api(url,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['x-csrf-token']=csrf;const form=body instanceof FormData;if(body&&!form)headers['Content-Type']='application/json';const response=await fetch(url,{method,headers,credentials:'same-origin',signal:lifetime.signal,body:body?form?body:JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw new Error('Respons server tidak dapat dibaca. Coba muat ulang.');}if(!response.ok){if(response.status===401&&workspace){workspace=null;user=null;csrf='';await authPage('login');}throw Object.assign(new Error(data.error||'Permintaan belum berhasil.'),{status:response.status});}return data;}
function toast(text,error=false){const box=$('#vs-toast');if(!box)return;box.className='vs-banner '+(error?'error':'success');box.innerHTML=`<span>${esc(text)}</span>${button('Tutup','dismiss-toast')}`;box.hidden=false;}
function ask(text,fn,label='Konfirmasi'){confirmation=fn;const box=root.querySelector('#vs-confirm');box.innerHTML=`<h2>${esc(text)}</h2><div class="vs-actions">${button(label,'confirm-yes','vs-primary')}${button('Kembali','confirm-no')}</div>`;box.addEventListener('cancel',()=>{confirmation=null;},{once:true});box.showModal();localize(box);box.querySelector('button').focus();}

async function load(){workspace=await api('/api/workspace');user=workspace.user;await Promise.all([smart.load(),market.load()]);if(!workspace.posts.some(x=>x.id===state.selected))state.selected=workspace.posts[0]?.id||null;}
async function mutate(url,method,body,view,message){await api(url,method,body);dirty=false;await load();if(view)state.view=view;render();if(message)toast(message);}
async function authPage(mode='login',email=''){if(disposed)return;
 authMode=mode;workspace=null;const setup=mode==='setup',invite=mode==='invite';
 root.innerHTML=`<div class="vs-auth-language">${languagePicker()}</div><div class="auth-layout"><section class="auth-brand"><div class="auth-logo"><img src="/brand/logo.svg" alt="Vayora.id"></div><span class="auth-tag">Social Studio</span><h1>Konten terencana.<br>Brand tetap konsisten.</h1><p>Siapkan konten, periksa detailnya, dan kelola jadwal publikasi Vayora dari satu workspace.</p><img class="auth-mascot" src="/brand/icon.svg" alt=""></section><section class="auth-form-wrap"><form class="auth-form" id="auth-form"><div><h2>${setup?'Buat akun pemilik':invite?'Bergabung ke workspace':'Masuk ke workspace'}</h2><p class="vs-sub">${setup?'Atur akun pertamamu untuk mulai mengelola konten Vayora.':invite?'Lengkapi nama dan buat password untuk akun tim.':'Gunakan akun tim Vayora untuk melanjutkan.'}</p></div><div id="auth-error" class="auth-error" role="alert" hidden></div>${setup||invite?'<label class="vs-label">Nama<input class="vs-input" name="name" id="auth-name" autocomplete="name" required minlength="2" maxlength="100"></label>':''}<label class="vs-label">Email<input class="vs-input" name="email" id="auth-email" type="email" autocomplete="username" value="${esc(email)}" required ${invite?'readonly':''}></label><label class="vs-label">Password<div class="auth-field"><input class="vs-input" name="password" id="auth-password" type="password" autocomplete="${setup||invite?'new-password':'current-password'}" required ${setup||invite?'minlength="12"':''} maxlength="128"><button class="auth-password-toggle" type="button" id="auth-show" aria-label="Tampilkan password">${icon('eye')}</button></div>${setup||invite?'<small>Minimal 12 karakter. Gunakan password yang berbeda dari Instagram.</small>':''}</label>${setup||invite?'<label class="vs-label">Ulangi password<input class="vs-input" name="confirm" id="auth-confirm" type="password" autocomplete="new-password" minlength="12" required></label>':'<label class="vs-check"><input type="checkbox" id="auth-remember"><span>Ingat saya selama 7 hari</span></label>'}<button class="vs-button vs-primary" id="auth-submit" type="submit">${setup?'Buat akun & masuk':invite?'Terima undangan':'Masuk'}${icon('arrow-right')}</button><p class="auth-foot">Login ini untuk Social Studio. Instagram dihubungkan secara terpisah melalui Pengaturan.</p></form></section></div>`;
 icons();$('#auth-show').addEventListener('click',()=>{const input=$('#auth-password');input.type=input.type==='password'?'text':'password';$('#auth-show').setAttribute('aria-label',input.type==='password'?'Tampilkan password':'Sembunyikan password');});
 $('#auth-form').addEventListener('submit',async event=>{event.preventDefault();const submit=$('#auth-submit');submit.disabled=true;$('#auth-error').hidden=true;try{const password=$('#auth-password').value;if((setup||invite)&&password!==$('#auth-confirm').value)throw new Error('Ulangi password dengan nilai yang sama.');const data=await api('/api/auth/'+(setup?'setup':invite?'accept-invite':'login'),'POST',{email:$('#auth-email').value,password,name:$('#auth-name')?.value,remember:$('#auth-remember')?.checked,token:inviteToken});csrf=data.csrf;user=data.user;state.view='calendar';pendingRoute='calendar';options.navigate?.('calendar',{replace:true});await load();render();}catch(e){$('#auth-error').textContent=e.message;$('#auth-error').hidden=false;}finally{if(submit.isConnected)submit.disabled=false;}});
}
function shell(){root.innerHTML=`<div class="vs-shell"><aside class="vs-sidebar"><div><div class="vs-brand"><img src="/brand/logo.svg" alt="Vayora.id"></div><p class="vs-brand-sub">Social Studio</p></div><nav class="vs-nav" id="vs-nav" aria-label="Navigasi workspace"></nav><div class="vs-side-bottom"><button type="button" data-action="nav:profile" class="vs-account-menu"><span class="vs-avatar">${esc(user.name[0].toUpperCase())}</span><span><b>${esc(user.name)}</b><br>${user.role==='owner'?'Pemilik workspace':'Editor'}</span></button><span id="vs-side-connection"></span>${button('Keluar','logout','','log-out')}</div></aside><main class="vs-work"><header class="vs-top"><span><b>Vayora</b> / Social Studio</span><div class="vs-top-actions"><span class="vs-header-status" id="vs-header-status"></span>${languagePicker()}</div></header><div class="vs-main"><div class="vs-heading"><div><h1 id="vs-title"></h1><p class="vs-sub" id="vs-subtitle"></p></div><div class="vs-actions" id="vs-header-actions"></div></div><div id="vs-toast" class="vs-banner success" role="status" hidden></div><div id="vs-mode-banner" class="vs-banner" hidden></div><dialog id="vs-confirm" class="vs-confirm-dialog" aria-label="Konfirmasi"></dialog><div id="vs-view" class="vs-stack"></div><p class="vs-footer">${icon('clock-3')}Waktu Indonesia Barat · Perubahan tersimpan di workspace</p></div></main><nav class="vs-bottom-nav" aria-label="Navigasi utama">${bottomNavigation()}</nav></div>`;}
function previewImage(item,klass='vs-thumb',index=0){const m=item.media[index]||item.media[0];const source=item.cover?.url||m?.posterUrl||m?.url||'/brand/icon.svg';return`<img class="${klass}" src="${source}" alt="${esc(item.alt||item.title)}" loading="lazy">`;}
function preview(item,editor=false){if(!item)return'';const media=item.media[slide]||item.media[0];const artwork=item.format==='Reel'?`<video id="vs-reel" class="vs-preview-video" controls playsinline preload="metadata" poster="${item.cover?.url||item.media[0]?.posterUrl||''}" aria-label="Pratinjau ${esc(item.title)}"><source src="${media.url}" type="video/mp4"></video>`:`<img class="vs-preview-image" src="${media?.url||'/brand/icon.svg'}" alt="${esc(item.alt)}">`;return`<h2>Pratinjau Instagram</h2><div class="vs-ig"><div class="vs-ig-top"><img src="/brand/icon.svg" alt=""><div><b>${esc(workspace.instagram.username||'Vayora')}</b><span>${esc(item.format)}${item.media[0]?.duration?' · '+Math.round(item.media[0].duration)+' detik':''}</span></div></div><div class="vs-preview-art">${artwork}</div>${item.format==='Carousel'?`<div class="vs-slidebar">${button('','slide-prev','vs-icon-button','chevron-left','aria-label="Slide sebelumnya"')}<span>Slide ${slide+1} dari ${item.media.length}</span>${button('','slide-next','vs-icon-button','chevron-right','aria-label="Slide berikutnya"')}</div>`:''}<div class="vs-ig-icons">${icon('heart')}${icon('message-circle')}${icon('send')}${icon('bookmark')}</div><p class="vs-ig-caption"><b>${esc(workspace.instagram.username||'Vayora')}</b> <span id="vs-caption-live">${esc(item.caption)}</span></p></div>${editor&&item.format==='Reel'?`${button('Gunakan frame sebagai cover','capture-cover','','image')}<p class="vs-mini" id="vs-cover-note">Putar atau geser video, lalu pilih frame untuk cover.</p>`:''}${!editor?`<div>${badge(item)}<p class="vs-sub">${esc(item.id)} · ${esc(item.category)}</p><p class="vs-mini">${esc(item.goal)}</p></div>${button('Buka detail konten','edit:'+item.id,'','pencil-line')}`:''}`;}
function record(item,queue=false){return`<${queue?'div':'button'} class="vs-record" ${queue?'':'type="button" data-action="select:'+item.id+'" aria-pressed="'+(item.id===state.selected)+'"'}>${previewImage(item)}<span class="vs-record-copy"><span class="vs-record-title">${esc(item.title)}</span><span class="vs-record-meta">${esc(item.id)} · ${esc(item.format)}</span><span class="vs-record-meta">${badge(item)}${item.scheduleAt?`<span>${nice(item.date)} · ${esc(item.time)} WIB</span>`:''}</span></span>${queue?`<div class="vs-actions">${button('Detail','delivery:'+item.id)}${item.status==='scheduled'?button('Batalkan','cancel:'+item.id,'vs-danger'):''}</div>`:''}</${queue?'div':'button'}>`;}
function selectField(id,label,options,value){return`<label class="vs-label"><span class="vs-mini">${label}</span><select id="${id}" class="vs-input vs-filter">${options.map(([key,text])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;}
function calendar(){const dates=Array.from({length:7},(_,i)=>addDays(monday(state.anchor),i));const planned=workspace.posts.filter(x=>x.status==='scheduled'||x.status==='processing');let grid='';const rangeTitle=state.mode==='month'?new Intl.DateTimeFormat(locale(),{month:'long',year:'numeric',timeZone:'UTC'}).format(dateObj(state.anchor)):new Intl.DateTimeFormat(locale(),{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).formatRange(dateObj(dates[0]),dateObj(dates[6]));if(state.mode==='week')grid=`<div class="vs-days">${dates.map((date,i)=>`<button type="button" class="vs-day" data-action="day:${date}" aria-pressed="${state.day===date}"><span>${['Sen','Sel','Rab','Kam','Jum','Sab','Min'][i]}</span><strong>${Number(date.slice(8))}</strong><span class="vs-dots">${planned.filter(x=>x.date===date).slice(0,3).map(()=>'<i class="vs-dot"></i>').join('')}</span></button>`).join('')}</div>`;if(state.mode==='month'){const first=state.anchor.slice(0,7)+'-01';const last=dateObj(first);last.setUTCMonth(last.getUTCMonth()+1);last.setUTCDate(0);const end=addDays(monday(last.toISOString().slice(0,10)),6);const days=[];for(let date=monday(first);date<=end;date=addDays(date,1))days.push(date);grid=`<div class="vs-month">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<div class="vs-weekday">${x}</div>`).join('')}${days.map(date=>{const posts=planned.filter(x=>x.date===date);return`<button type="button" class="vs-cell ${date.slice(0,7)!==first.slice(0,7)?'other':''}" data-action="day:${date}" aria-pressed="${state.day===date}" aria-label="${esc(fullDate(date))}, ${posts.length} posting"><span class="vs-cell-day">${Number(date.slice(8))}</span>${posts.slice(0,2).map(x=>`<span class="vs-month-event">${esc(x.id)} · ${esc(x.time)}</span>`).join('')}${posts.length?`<span class="vs-month-count">${posts.length} posting</span>`:''}</button>`;}).join('')}</div>`;}
const listed=planned.filter(x=>state.day?x.date===state.day:state.mode==='month'?x.date.slice(0,7)===state.anchor.slice(0,7):dates.includes(x.date)).sort((a,b)=>a.scheduleAt.localeCompare(b.scheduleAt));if(listed.length&&!listed.some(x=>x.id===state.selected))state.selected=listed[0].id;return`<div class="vs-stats"><span><strong>${workspace.posts.length}</strong> konten</span><span><strong>${count('draft')}</strong> draft</span><span><strong>${count('review')}</strong> perlu diperiksa</span><span><strong>${count('scheduled')}</strong> terjadwal</span></div><div class="vs-row"><div class="vs-actions">${button('','prev-period','vs-icon-button','chevron-left','aria-label="Periode sebelumnya"')}<span class="vs-period">${esc(rangeTitle)}</span>${button('','next-period','vs-icon-button','chevron-right','aria-label="Periode berikutnya"')}${button('Hari ini','today')}</div><div class="vs-segment" role="group" aria-label="Tampilan kalender">${[['week','Minggu'],['month','Bulan'],['agenda','Agenda']].map(([id,title])=>`<button type="button" data-action="mode:${id}" aria-pressed="${state.mode===id}">${title}</button>`).join('')}</div></div>${grid}<div class="vs-columns"><section class="vs-panel"><div class="vs-panel-head"><h2>${state.day?esc(fullDate(state.day)):'Jadwal publikasi'}</h2>${state.day?button('Semua tanggal','clear-day'):''}</div><div class="vs-list">${listed.length?listed.map(x=>record(x)).join(''):`<div class="vs-empty">${icon('calendar-plus')}<h3>Belum ada konten terjadwal.</h3><p>Mulai dengan memeriksa konten di pustaka, lalu pilih waktu tayangnya.</p>${button('Buka pustaka','nav:library','vs-primary')}</div>`}</div></section>${current()?'<aside id="vs-preview" class="vs-panel vs-preview"></aside>':''}</div>`;}
function matchesQuick(post,key){return key==='all'||key==='attention'&&['failed','uncertain','review'].includes(post.status)||post.status===key;}
function quickCount(key){return workspace.posts.filter(p=>matchesQuick(p,key)).length;}
function filteredPosts(){const q=state.search.trim().toLowerCase();return workspace.posts.filter(x=>(!q||[x.id,x.title,x.caption,x.category].join(' ').toLowerCase().includes(q))&&matchesQuick(x,state.quick)&&(state.format==='Semua'||x.format===state.format)&&(state.status==='Semua'||x.status===state.status)&&(state.goal==='Semua'||x.goal===state.goal)).sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title):state.sort==='schedule'?(a.scheduleAt||'9999').localeCompare(b.scheduleAt||'9999'):(b.updatedAt||'').localeCompare(a.updatedAt||'')||a.id.localeCompare(b.id));}
function updateLibraryResults(){const posts=filteredPosts();$('#library-grid').innerHTML=libraryCards(posts);$('#library-count').textContent=posts.length+' dari '+workspace.posts.length+' konten';icons();localize(root);}
function libraryCards(posts){return `${posts.map(item=>`<article class="vs-content-card" data-post-id="${esc(item.id)}"><button class="vs-card-open" type="button" data-action="edit:${item.id}" aria-label="${esc(translate('Detail konten')+' · '+item.title)}"><div class="vs-art">${previewImage(item,'')}<span class="vs-format">${esc(item.format)}${item.format==='Carousel'?' · '+item.media.length+' slide':''}</span></div><div class="vs-card-copy"><span class="vs-mini">${esc(item.id)} · ${esc(item.category)}</span><h3 data-user-content>${esc(item.title)}</h3><span class="vs-mini">${esc(item.goal)}</span><div>${badge(item)}</div><div class="vs-card-schedule">${cardTime(item)}</div></div></button><div class="vs-card-actions">${button('Post sekarang','post-now:'+item.id,'vs-primary','send',publishLocked(item)?'disabled title="Konten terkunci atau sudah dipublikasikan."':'')}${button('Detail','edit:'+item.id,'','maximize-2')}</div></article>`).join('')}${!posts.length?'<div class="vs-empty"><h3>Tidak ada konten dengan filter ini.</h3></div>':''}`;}
function library(){const posts=filteredPosts();return`<div class="vs-library-search"><label class="vs-search-field">${icon('search')}<input class="vs-input" id="library-search" placeholder="Cari judul, ID, atau caption" value="${esc(state.search)}" type="search" maxlength="200" aria-label="Cari konten"></label>${selectField('library-sort','Urutkan',[['newest','Terbaru diperbarui'],['title','Judul A–Z'],['schedule','Jadwal terdekat']],state.sort)}</div><div class="vs-quick-filters" role="group" aria-label="Filter cepat">${[['all','Semua'],['draft','Draft'],['scheduled','Terjadwal'],['published','Terbit'],['attention','Perlu tindakan']].map(([id,label])=>`<button type="button" data-action="quick-filter:${id}" aria-pressed="${state.quick===id}">${label}<span>${quickCount(id)}</span></button>`).join('')}</div><details class="vs-library-advanced" ${matchMedia('(min-width:801px)').matches?'open':''}><summary>${icon('sliders-horizontal')}Filter lainnya</summary><div class="vs-controls">${selectField('filter-format','Format',[['Semua','Semua format'],['Reel','Reels'],['Gambar','Gambar'],['Carousel','Carousel']],state.format)}${selectField('filter-status','Status',[['Semua','Semua status'],...Object.entries(names)],state.status)}${selectField('filter-goal','Tujuan',[['Semua','Semua tujuan'],...goals.map(x=>[x,x])],state.goal)}</div></details><p id="library-count" class="vs-mini">${posts.length} dari ${workspace.posts.length} konten</p><div id="library-grid" class="vs-card-grid">${libraryCards(posts)}</div>`;}
function editor(){const item=draft;return`<div>${button(state.modal?'Tutup detail':'Kembali ke pustaka',state.modal?'close-detail':'nav:library','','arrow-left')}</div><div class="vs-columns"><section class="vs-panel vs-form"><div class="vs-row"><div><span class="vs-eyebrow">${esc(item.id)} · ${esc(item.format)}</span><h2 data-user-content>${esc(item.title)}</h2></div>${badge(current())}</div><label class="vs-label">Judul konten<input class="vs-input" id="edit-title" value="${esc(item.title)}" maxlength="180" required></label><details class="vs-assistant-fold"><summary>${icon('sparkles')}Asisten caption & hashtag</summary>${smart.editorPanel()}</details><label class="vs-label">Caption<textarea class="vs-input" id="edit-caption" maxlength="2200">${esc(item.caption)}</textarea><small id="caption-count">${item.caption.length} / 2.200 karakter</small></label><div class="vs-two"><label class="vs-label">Kategori<select class="vs-input" id="edit-category">${categories.map(x=>`<option ${x===item.category?'selected':''}>${x}</option>`).join('')}</select></label><label class="vs-label">Tujuan konten<select class="vs-input" id="edit-goal">${goals.map(x=>`<option ${x===item.goal?'selected':''}>${x}</option>`).join('')}</select></label></div>${item.format!=='Reel'?`<label class="vs-label">Deskripsi gambar<textarea class="vs-input" id="edit-alt" maxlength="1000" style="min-height:70px">${esc(item.alt)}</textarea><small>Deskripsi yang membantu pengguna pembaca layar.</small></label>`:''}${item.format==='Carousel'?'<div class="vs-stack"><h3>Urutan slide</h3><div class="vs-slide-list" id="slide-list"></div></div>':''}<div class="vs-banner" id="approval-note" hidden><span>Konten berubah. Periksa kembali sebelum memberikan persetujuan.</span></div><label class="vs-check"><input type="checkbox" id="edit-approved" ${item.approved?'checked':''}><span>Media dan caption sudah diperiksa.<br><span class="vs-mini">Termasuk cover, urutan slide, harga, dan informasi penawaran.</span></span></label><div class="vs-divider"></div><div class="vs-two"><label class="vs-label">Tanggal tayang<input class="vs-input" type="date" id="edit-date" min="${today()}" value="${esc(item.date||addDays(today(),1))}" required></label><label class="vs-label">Jam WIB<input class="vs-input" type="time" id="edit-time" value="${esc(item.time||'12:00')}" required></label></div>${smart.timePanel()}${versionHistory()}<div id="editor-readiness">${readinessHTML(draftReadiness())}</div>${!workspace.instagram.connected?'<p class="vs-mini">Kamu dapat menyimpan jadwal untuk perencanaan. Publikasi menunggu Instagram terhubung dan diaktifkan oleh pemilik.</p>':''}<p class="vs-inline-error" id="editor-error" role="alert" hidden></p><div class="vs-actions">${button('Simpan jadwal','save:scheduled','vs-primary','calendar-check')}${button('Tandai siap tayang','save:ready','','check')}${button('Ajukan pemeriksaan','save:review')}${button('Simpan draft','save:draft')}</div></section><aside class="vs-panel vs-preview" id="vs-preview"></aside></div>`;}
function review(){const items=workspace.posts.filter(x=>x.status==='review');return`<div class="vs-stats"><span><strong>${items.length}</strong> perlu diperiksa</span><span><strong>${count('ready')}</strong> siap tayang</span></div><section class="vs-panel"><div class="vs-panel-head"><h2>Periksa media dan caption</h2></div><div class="vs-list">${items.map(item=>`<div class="vs-record">${previewImage(item)}<div class="vs-record-copy"><h3>${esc(item.title)}</h3><span class="vs-mini">${esc(item.id)} · ${esc(item.goal)}</span></div><div class="vs-actions">${button('Periksa','edit:'+item.id,'vs-primary','clipboard-check')}</div></div>`).join('')||'<div class="vs-empty"><h3>Tidak ada pemeriksaan tertunda.</h3><p>Ajukan konten melalui editor setelah caption dan medianya lengkap.</p></div>'}</div></section>`;}
function queue(){const items=workspace.posts.filter(x=>['scheduled','processing','failed','uncertain'].includes(x.status)).sort((a,b)=>(a.scheduleAt||'').localeCompare(b.scheduleAt||''));return`<div class="vs-row"><div class="vs-stats"><span><strong>${count('scheduled')}</strong> terjadwal</span><span><strong>${count('failed')+count('uncertain')}</strong> perlu tindakan</span></div>${button(workspace.settings.paused?'Lanjutkan antrean':'Jeda semua posting','pause',workspace.settings.paused?'vs-primary':'',workspace.settings.paused?'play':'pause')}</div><section class="vs-panel"><div class="vs-panel-head"><h2>Antrean publikasi</h2></div><div class="vs-list">${items.map(x=>record(x,true)).join('')||'<div class="vs-empty"><h3>Antrean masih kosong.</h3><p>Konten yang kamu jadwalkan akan tampil di sini.</p></div>'}</div></section><p class="vs-mini">Jadwal terlewat lebih dari lima menit memerlukan penjadwalan ulang. Pastikan aplikasi tetap berjalan saat publikasi diaktifkan.</p>`;}
function delivery(){const item=current();return`<div>${button(state.modal?'Tutup detail':'Kembali ke antrean',state.modal?'close-detail':'nav:queue','','arrow-left')}</div><div class="vs-columns"><section class="vs-panel vs-pad vs-stack"><div class="vs-row"><div><span class="vs-eyebrow">${esc(item.id)} · ${esc(item.format)}</span><h2 data-user-content>${esc(item.title)}</h2></div>${badge(item)}</div>${item.scheduleAt?`<p class="vs-sub">${stamp(item.scheduleAt)}</p>`:''}${item.error?`<div class="vs-banner error"><span>${esc(item.error)}</span></div>`:''}${item.status==='published'?`<div class="vs-banner success"><span>Konten telah terbit. Publikasi ulang diblokir untuk mencegah duplikat.</span></div>${item.permalink?`<a class="vs-button" href="${esc(item.permalink)}" target="_blank" rel="noopener noreferrer">Lihat di Instagram</a>`:'<p class="vs-mini">Hasil tercatat; tautan posting belum tersedia.</p>'}`:''}<div class="vs-timeline">${[['clipboard-check','Pemeriksaan',item.approved?'Media dan caption disetujui.':'Menunggu persetujuan.'],['instagram','Koneksi Instagram',workspace.instagram.connected?'@'+workspace.instagram.username:'Belum terhubung.'],['calendar-clock','Antrean',workspace.settings.paused?'Sedang dijeda.':'Antrean berjalan.'],['shield-check','Hasil publikasi',item.mediaId?'ID hasil: '+item.mediaId:item.job?.publishRequested?'Permintaan pernah dikirim. Status perlu dipastikan.':'Belum ada hasil publikasi.']].map(([ic,title,detail])=>`<div class="vs-log"><span class="vs-log-mark">${icon(ic)}</span><div><h3>${title}</h3><p class="vs-sub">${esc(detail)}</p></div></div>`).join('')}</div><div class="vs-actions">${item.status==='failed'&&!item.job?.publishRequested?button('Jadwalkan ulang','retry:'+item.id,'vs-primary','refresh-cw'):''}${item.job?.containerId&&item.status!=='published'?button('Periksa hasil di Meta','reconcile:'+item.id,'vs-primary'):''}${!['published','processing','uncertain'].includes(item.status)?button('Ubah konten','edit:'+item.id):''}${button('Buat salinan','duplicate:'+item.id,'','copy')}</div></section><aside class="vs-panel vs-preview" id="vs-preview"></aside></div>`;}
function historyView(){const events=workspace.events.filter(x=>state.history==='Semua'||x.type===state.history);return`<div class="vs-controls">${selectField('filter-history','Aktivitas',[['Semua','Semua aktivitas'],['published','Publikasi berhasil'],['failed','Kendala publikasi'],['change','Perubahan konten'],['connection','Koneksi Instagram'],['account','Akun tim']],state.history)}</div><section class="vs-panel vs-pad"><div class="vs-timeline">${events.map(event=>`<div class="vs-log"><span class="vs-log-mark">${icon(event.type==='published'?'check':event.type==='failed'?'triangle-alert':'history')}</span><div class="vs-stack" style="gap:5px"><div class="vs-row"><h3>${esc(event.title)}${event.post_id?' · '+esc(event.post_id):''}</h3><span class="vs-mini">${stamp(event.created_at)}</span></div><p>${esc(event.detail)}</p>${event.post_id?`<div>${button('Lihat detail','delivery:'+event.post_id)}</div>`:''}</div></div>`).join('')||'<div class="vs-empty"><h3>Belum ada aktivitas pada kategori ini.</h3></div>'}</div></section>`;}
function importView(){if(state.importStep===1)return`<div class="vs-stepbar"><span class="active"><b>1</b>Pilih file</span><span><b>2</b>Cocokkan konten</span><span><b>3</b>Selesai</span></div><section class="vs-panel vs-pad vs-stack"><div class="vs-upload">${icon('upload')}<h2>Masukkan media sekaligus</h2><p class="vs-sub">Video, gambar, dan slide carousel dari produksi Vayora.</p><label class="vs-label">Pilih media<input type="file" id="import-files" multiple accept="image/jpeg,image/png,image/webp,video/mp4"></label><p class="vs-mini">Video maksimal 100 MB per file. Contoh: V01-kamar.mp4, I01-kamar.jpg, C01-slide-1.png.</p></div><p id="import-progress" class="vs-mini" role="status"></p></section>`;if(state.importStep===3)return`<section class="vs-panel vs-pad vs-stack"><h2>Impor selesai.</h2><p class="vs-sub">Konten baru disimpan sebagai draft untuk diperiksa.</p><div class="vs-actions">${button('Buka pustaka','nav:library','vs-primary')}${button('Impor lagi','import-again')}</div></section>`;return`<div class="vs-stepbar"><span><b>1</b>Pilih file</span><span class="active"><b>2</b>Cocokkan konten</span><span><b>3</b>Selesai</span></div><section class="vs-panel vs-pad"><label class="vs-label">Caption pendamping <small>Opsional · cocokkan berdasarkan ID</small><input type="file" id="caption-file" accept=".md,.json,.csv"><small>Markdown daftar caption Vayora, JSON, atau CSV dengan kolom id dan caption.</small></label></section><div class="vs-mapping">${importGroups.map((item,i)=>`<section class="vs-import-row"><div class="vs-map-header"><h3>${esc(item.id)} · ${esc(item.format)} · ${item.mediaIds.length} file</h3><span class="vs-status ${workspace.posts.some(x=>x.id===item.id)?'review':'ready'}">${workspace.posts.some(x=>x.id===item.id)?'Sudah ada · dilewati':'Konten baru'}</span></div><div class="vs-two"><label class="vs-label">ID<input class="vs-input" data-map-id="${i}" value="${esc(item.id)}" maxlength="24"></label><label class="vs-label">Judul<input class="vs-input" data-map-title="${i}" value="${esc(item.title)}" maxlength="180"></label></div><label class="vs-label">Caption<textarea class="vs-input vs-import-caption" data-map-caption="${i}">${esc(item.caption)}</textarea></label></section>`).join('')}</div><div class="vs-actions">${button('Impor sebagai draft','commit-import','vs-primary','download')}${button('Pilih ulang','import-again')}</div>`;}
function settings(){const c=workspace.instagram,owner=user.role==='owner';return`<section class="vs-panel vs-pad"><div class="vs-setting"><div><h2>Instagram Vayora</h2><p class="vs-sub">${c.username?'@'+esc(c.username):'Hubungkan akun Business atau Creator.'}</p></div><span class="vs-status ${c.connected?'scheduled':'review'}">${c.connected?'Terhubung':c.expiresAt?'Perlu sambung ulang':'Belum terhubung'}</span></div><div class="vs-setting"><div><h3>Koneksi akun</h3><p class="vs-sub">Password Instagram dimasukkan hanya pada halaman resmi Meta.</p></div>${owner?button(c.connected?'Periksa koneksi':'Hubungkan Instagram',c.connected?'ig-check':'ig-connect','vs-primary','instagram'):'<span class="vs-mini">Dikelola pemilik workspace</span>'}</div>${c.connected&&owner?`<div class="vs-setting"><p class="vs-mini">Izin berlaku hingga ${stamp(new Date(c.expiresAt).toISOString())}.</p>${button('Putuskan koneksi','ig-disconnect','vs-danger')}</div>`:''}<div class="vs-setting"><div><h3>Publikasi nyata</h3><p class="vs-sub">${workspace.settings.publishingEnabled?'Diaktifkan. Konten terjadwal mengikuti status antrean.':'Belum diaktifkan. Konten dan jadwal tetap bisa dipersiapkan.'}</p></div>${owner?button(workspace.settings.publishingEnabled?'Nonaktifkan publikasi':'Aktifkan publikasi',workspace.settings.publishingEnabled?'disable-live':'enable-live','','power'):''}</div><div class="vs-setting"><div><h3>Zona waktu</h3><p class="vs-sub">Semua jadwal menggunakan Waktu Indonesia Barat.</p></div><span class="vs-status">Asia/Jakarta · UTC+7</span></div><div class="vs-setting"><label class="vs-check"><input id="notify-failure" type="checkbox" ${workspace.settings.notifyFailure?'checked':''}><span>Tampilkan kendala publikasi di workspace.</span></label></div><div class="vs-setting"><label class="vs-check"><input id="notify-reconnect" type="checkbox" ${workspace.settings.notifyReconnect?'checked':''}><span>Tampilkan pengingat sambungkan ulang akun.</span></label></div></section>${owner?`<section class="vs-panel vs-pad vs-stack"><div><h2>Konfigurasi aplikasi Meta</h2><p class="vs-sub">${c.configured?'App ID dan secret sudah tersedia.':'Belum ada aplikasi Meta. Login tim tetap berfungsi.'}</p></div><form class="vs-stack" id="meta-form"><label class="vs-label">Instagram App ID<input class="vs-input" id="meta-id" value="${esc(c.appId)}" inputmode="numeric" autocomplete="off"></label><label class="vs-label">Instagram App Secret<input class="vs-input" id="meta-secret" type="password" autocomplete="new-password" placeholder="${c.configured?'Kosongkan untuk mempertahankan secret tersimpan':'Isi setelah membuat aplikasi Meta'}"><small>Disimpan terenkripsi di server dan tidak ditampilkan kembali.</small></label><div class="vs-two"><label class="vs-label">Alamat HTTPS publik<input class="vs-input" id="meta-url" type="url" value="${esc(c.publicBase)}" placeholder="https://studio.domainkamu.id"></label><label class="vs-label">Versi API<input class="vs-input" id="meta-version" value="${esc(c.version||'v27.0')}"></label></div><div><button class="vs-button" type="submit">Simpan konfigurasi</button></div>${c.callbackUrl?`<p class="vs-mini">Callback yang perlu didaftarkan: <span class="vs-invite-link">${esc(c.callbackUrl)}</span></p>`:''}</form></section>`:''}<section class="vs-panel vs-pad vs-stack"><h2>Langkah menghubungkan Instagram</h2><ol class="vs-help-list"><li>Ubah akun Instagram Vayora menjadi Business atau Creator.</li><li>Buat aplikasi di <a href="https://developers.facebook.com/apps/" target="_blank" rel="noopener noreferrer">Meta Developer</a>, lalu pilih Instagram API dengan Instagram Login.</li><li>Tambahkan akun Vayora sebagai tester selama pengujian dan terima undangannya di Instagram.</li><li>Siapkan HTTPS publik, daftarkan callback di atas, dan isi App ID serta App Secret.</li><li>Tekan Hubungkan Instagram, login pada halaman resmi Meta, dan setujui izin publikasi.</li><li>Periksa koneksi dan satu konten uji sebelum mengaktifkan publikasi nyata.</li></ol><p class="vs-mini">Panduan lengkap tersedia dalam folder proyek: README dan docs/INSTAGRAM.md.</p></section>`;}
function profile(){return`<section class="vs-panel vs-pad vs-stack"><div><h2>${esc(user.name)}</h2><p class="vs-sub">${esc(user.email)} · ${user.role==='owner'?'Pemilik workspace':'Editor'}</p></div><form id="password-form" class="vs-stack"><h3>Ganti password</h3><label class="vs-label">Password saat ini<input class="vs-input" type="password" id="password-current" autocomplete="current-password" required></label><div class="vs-two"><label class="vs-label">Password baru<input class="vs-input" type="password" id="password-new" minlength="12" maxlength="128" autocomplete="new-password" required></label><label class="vs-label">Ulangi password baru<input class="vs-input" type="password" id="password-confirm" autocomplete="new-password" required></label></div><div><button class="vs-button" type="submit">Ganti password</button></div></form></section>${user.role==='owner'?`<section class="vs-panel vs-pad vs-stack"><h2>Undang editor</h2><p class="vs-sub">Editor dapat mengelola konten dan jadwal. Koneksi Instagram tetap dikelola pemilik.</p><form id="invite-form" class="vs-stack"><label class="vs-label">Email anggota tim<input class="vs-input" type="email" id="invite-email" required></label><div><button type="submit" class="vs-button vs-primary">Buat tautan undangan</button></div></form><div id="invite-result" hidden></div></section>`:''}<div>${button('Keluar dari workspace','logout','','log-out')}</div>`;}
function render(){if(disposed||!workspace)return;shell();$('#vs-nav').innerHTML=navigationHTML({view:state.view,reviewCount:count('review'),icon});const headings={marketing:['Marketing','Ukur campaign, pelajari performa, dan catat permintaan demo.'],assistant:['Asisten caption','Tulis caption dan hashtag dari media yang kamu pilih.'],designer:['Desain konten','Susun image post dengan logo, warna, dan visual Vayora.'],knowledge:['Pengetahuan brand','Telusuri fakta produk dan pedoman yang menjadi acuan AI.'],'ai-settings':['Pengaturan AI','Atur koneksi AI, batas penggunaan, dan arah penulisan brand.'],strategy:['Strategi konten','Panduan pesan, pencarian sosial, dan eksperimen campaign.'],calendar:['Kalender konten','Rencanakan publikasi dengan waktu dan alur yang jelas.'],library:['Pustaka konten','Media asli, caption, dan tujuan konten Vayora.'],review:['Pemeriksaan konten','Pastikan informasi dan tampilan siap mewakili Vayora.'],queue:['Antrean publikasi','Pantau jadwal dan tangani konten yang memerlukan tindakan.'],history:['Riwayat aktivitas','Hasil publikasi dan perubahan konten tercatat di sini.'],editor:['Atur posting','Periksa media, lengkapi caption, lalu tentukan waktunya.'],import:['Impor konten','Kelompokkan file dan cocokkan caption melalui ID konten.'],settings:['Pengaturan','Koneksi Instagram dan preferensi publikasi.'],profile:['Akun tim','Profil, keamanan akun, dan akses workspace.'],delivery:['Detail publikasi','Periksa status dan langkah berikutnya.']};const [title,sub]=headings[state.view]||headings.calendar;$('#vs-title').textContent=title;$('#vs-subtitle').textContent=sub;$('#vs-side-connection').textContent=workspace.instagram.connected?'Instagram @'+workspace.instagram.username:'Instagram belum terhubung';$('#vs-header-status').textContent=workspace.settings.publishingEnabled?'Publikasi nyata aktif':'Mode perencanaan';$('#vs-header-actions').innerHTML=['library','calendar','review','queue'].includes(state.view)?button('Impor konten','nav:import','','upload'):'';if(!workspace.settings.publishingEnabled){$('#vs-mode-banner').hidden=false;$('#vs-mode-banner').innerHTML=`<span><b>Mode perencanaan.</b> Login, media, dan jadwal tersimpan. Publikasi Instagram belum diaktifkan.</span>${button('Siapkan Instagram','nav:settings')}`;}else if(workspace.settings.paused){$('#vs-mode-banner').hidden=false;$('#vs-mode-banner').innerHTML=`<span><b>Antrean dijeda.</b> Jadwal tetap tersimpan.</span>${button('Lanjutkan','pause','vs-primary')}`;}else if(!workspace.instagram.connected){$('#vs-mode-banner').hidden=false;$('#vs-mode-banner').innerHTML=`<span>Koneksi Instagram perlu disambungkan ulang. Publikasi menunggu koneksi aktif.</span>${button('Pengaturan','nav:settings')}`;}if(!['calendar','library','queue','review','editor','settings','delivery'].includes(state.view))$('#vs-mode-banner').hidden=true;const views={designer:smart.designerPage,knowledge:smart.knowledgePage,'ai-settings':smart.aiSettingsPage,strategy:smart.strategyPage,marketing:market.page,assistant:smart.page,calendar,library,editor,review,queue,delivery,history:historyView,import:importView,settings,profile};$('#vs-view').innerHTML=(views[state.view]||calendar)();if($('#vs-preview'))$('#vs-preview').innerHTML=preview(state.view==='editor'?draft:current(),state.view==='editor');if(state.view==='editor'){renderSlides();bindEditor();}bindView();if(state.modal)renderDetail();icons();localize(root);for(const post of workspace.posts.filter(p=>p.status==='processing'))pollPublication(post.id);}
function renderSlides(){if(!$('#slide-list'))return;$('#slide-list').innerHTML=draft.media.map((m,i)=>`<div class="vs-slide-row"><img src="${m.url}" alt="Slide ${i+1}"><span class="vs-mini">Slide ${i+1} · ${esc(m.name)}</span><div class="vs-actions">${button('','up:'+i,'vs-icon-button','arrow-up',`aria-label="Pindah slide ${i+1} ke atas" ${i===0?'disabled':''}`)}${button('','down:'+i,'vs-icon-button','arrow-down',`aria-label="Pindah slide ${i+1} ke bawah" ${i===draft.media.length-1?'disabled':''}`)}</div></div>`).join('');}
function markDirty(){dirty=true;draft.approved=false;$('#edit-approved').checked=false;$('#approval-note').hidden=false;$('#editor-error').hidden=true;refreshDraftReadiness();}
function readEditor(){Object.assign(draft,{title:$('#edit-title').value,caption:$('#edit-caption').value,alt:$('#edit-alt')?.value??draft.alt,category:$('#edit-category').value,goal:$('#edit-goal').value,date:$('#edit-date').value,time:$('#edit-time').value,approved:$('#edit-approved').checked});refreshDraftReadiness();}
function bindEditor(){$('#edit-caption').addEventListener('input',()=>{draft.caption=$('#edit-caption').value;$('#vs-caption-live').textContent=draft.caption;$('#caption-count').textContent=`${draft.caption.length} / 2.200 karakter`;markDirty();});$('#edit-title').addEventListener('input',markDirty);$('#edit-alt')?.addEventListener('input',()=>{draft.alt=$('#edit-alt').value;markDirty();});for(const id of ['edit-category','edit-goal'])$('#'+id).addEventListener('change',()=>{readEditor();markDirty();});for(const id of ['edit-date','edit-time','edit-approved'])$('#'+id).addEventListener('change',()=>{readEditor();dirty=true;$('#editor-error').hidden=true;});}
function navigate(view){if(!pageIds.includes(view))return;const move=()=>{dirty=false;state.modal=null;draft=null;state.view=view;pendingRoute=view;options.navigate?.(view);render();window.scrollTo({top:0,behavior:'instant'});};if((state.view==='editor'||state.modal==='content')&&dirty){ask('Perubahan belum disimpan. Tinggalkan editor?',move,'Tinggalkan');return;}move();}
async function openCaption(id){openEditor(id);await enterEdit();const fold=$('.vs-assistant-fold');fold.open=true;fold.querySelector('summary').focus({preventScroll:true});fold.scrollIntoView({block:'start',behavior:'auto'});}

function openEditor(id){state.returnAction='edit:'+id;state.selected=id;draft=null;smart.reset();dirty=false;slide=0;state.detailMode='summary';state.versions=[];state.versionId='';state.modal='content';renderDetail();}

function bindView(){smart.bind();market.bind();$('#library-search')?.addEventListener('input',e=>{state.search=e.target.value;updateLibraryResults();});$('#library-sort')?.addEventListener('change',e=>{state.sort=e.target.value;updateLibraryResults();});for(const [id,key] of [['filter-format','format'],['filter-status','status'],['filter-goal','goal'],['filter-history','history']])$('#'+id)?.addEventListener('change',e=>{state[key]=e.target.value;render();});for(const [id,key] of [['notify-failure','notifyFailure'],['notify-reconnect','notifyReconnect']])$('#'+id)?.addEventListener('change',e=>void run(()=>mutate('/api/workspace/settings','POST',{[key]:e.target.checked},null,'Preferensi disimpan.')));$('#import-files')?.addEventListener('change',e=>void run(()=>importFiles([...e.target.files])));$('#caption-file')?.addEventListener('change',e=>void run(async()=>{captureMapping();await importCaptions(e.target.files[0]);render();toast('Caption dicocokkan berdasarkan ID.');}));$('#meta-form')?.addEventListener('submit',e=>{e.preventDefault();void run(()=>mutate('/api/instagram/config','POST',{appId:$('#meta-id').value,appSecret:$('#meta-secret').value,publicBase:$('#meta-url').value,version:$('#meta-version').value},'settings','Konfigurasi disimpan. Publikasi tetap nonaktif hingga kamu mengaktifkannya.'));});$('#password-form')?.addEventListener('submit',e=>{e.preventDefault();void run(async()=>{if($('#password-new').value!==$('#password-confirm').value)throw new Error('Ulangi password baru dengan nilai yang sama.');await api('/api/auth/password','POST',{currentPassword:$('#password-current').value,password:$('#password-new').value});await load();render();toast('Password diperbarui. Sesi lain sudah dikeluarkan.');});});$('#invite-form')?.addEventListener('submit',e=>{e.preventDefault();void run(async()=>{const data=await api('/api/team/invites','POST',{email:$('#invite-email').value});$('#invite-result').hidden=false;$('#invite-result').innerHTML=`<p class="vs-mini">Berlaku 48 jam dan hanya dapat digunakan sekali. Kirim tautan ini kepada anggota tim.</p><p class="vs-invite-link">${esc(data.url)}</p>`;});});}
async function run(fn,target){if(busy)return;busy=true;root.setAttribute('aria-busy','true');if(target)target.disabled=true;try{await fn();}catch(e){if((state.view==='editor'||state.modal==='content')&&$('#editor-error')){$('#editor-error').textContent=e.message;$('#editor-error').hidden=false;}else if($('#detail-error')){$('#detail-error').textContent=e.message;$('#detail-error').hidden=false;}else if($('#publish-error')){$('#publish-error').textContent=e.message;$('#publish-error').hidden=false;}else toast(e.message,true);}finally{busy=false;root.setAttribute('aria-busy','false');if(target?.isConnected)target.disabled=false;}}
async function save(intent){const popup=!!state.modal;readEditor();if(!draft.title.trim())throw new Error('Isi judul konten.');const payload={...draft,mediaIds:draft.media.map(x=>x.id),intent};await api('/api/posts/'+draft.id,'PUT',payload);dirty=false;await load();state.selected=draft.id;if(popup){state.modal=null;}else if(intent==='scheduled'){state.anchor=draft.date;state.day=draft.date;state.view='calendar';}else state.view=intent==='review'?'review':'library';draft=null;render();toast(intent==='scheduled'?'Jadwal tersimpan. Publikasi mengikuti status koneksi dan antrean.':intent==='ready'?'Konten siap tayang.':intent==='review'?'Konten diajukan untuk diperiksa.':'Draft tersimpan.');}
async function upload(files,role='content'){const data=new FormData();files.forEach(f=>data.append('files',f));return(await api('/api/media'+(role==='cover'?'?role=cover':''),'POST',data)).media;}
async function captureCover(){const video=$('#vs-reel');if(!video||video.readyState<2)throw new Error('Putar video atau geser waktunya sampai preview siap.');const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=Math.round(1080*video.videoHeight/video.videoWidth);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.94));if(!blob)throw new Error('Cover tidak dapat dibuat.');const [media]=await upload([new File([blob],draft.id+'-cover.jpg',{type:'image/jpeg'})],'cover');draft.cover=media;draft.coverId=media.id;draft.coverTime=Math.round(video.currentTime*1000)/1000;markDirty();$('#vs-cover-note').textContent='Cover dipilih dari detik '+draft.coverTime+'. Simpan konten untuk menyimpan pilihan ini.';toast('Cover siap. Periksa kembali sebelum memberikan persetujuan.');}
async function importFiles(files){if(!files.length)return;if(files.length>100)throw new Error('Pilih maksimal 100 file sekaligus.');const accepted=files.filter(f=>!/^Vayora-C\d+-Carousel\.mp4$/i.test(f.name));const progress=$('#import-progress');progress.textContent='Mengunggah dan memeriksa '+accepted.length+' file…';const media=await upload(accepted);const groups=new Map();let next=1;for(let i=0;i<accepted.length;i++){const file=accepted[i],m=media[i];const car=file.name.match(/(?:^|[-_ ])(C\d+)[-_ ]slide[-_ ]?(\d+)/i),single=file.name.match(/(?:^|[-_ ])([VI]\d+)(?:[-_. ]|$)/i);const format=car?'Carousel':m.mime==='video/mp4'?'Reel':'Gambar';const id=(car?.[1]||single?.[1]||'BARU'+next++).toUpperCase();let group=groups.get(id);if(group&&format!=='Carousel')throw new Error('Ada beberapa file dengan ID '+id+'. Ganti nama salah satu file.');if(!group){group={id,title:file.name.replace(/\.[^.]+$/,'').replace(/[-_]+/g,' '),format,caption:'',alt:'',category:'Operasional',goal:'Pengenalan brand',media:[]};groups.set(id,group);}group.media.push({...m,number:car?Number(car[2]):0});}importGroups=[...groups.values()].map(g=>({...g,media:g.media.sort((a,b)=>a.number-b.number),mediaIds:g.media.map(x=>x.id)}));state.importStep=2;render();}
function captureMapping(){for(const el of $$('[data-map-id]'))importGroups[Number(el.dataset.mapId)].id=el.value.trim().toUpperCase();for(const el of $$('[data-map-title]'))importGroups[Number(el.dataset.mapTitle)].title=el.value.trim();for(const el of $$('[data-map-caption]'))importGroups[Number(el.dataset.mapCaption)].caption=el.value;}
function parseCSV(text){const rows=[];let row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v='';}else v+=c;}row.push(v);if(row.some(x=>x.trim()))rows.push(row);const head=(rows.shift()||[]).map(x=>x.trim().toLowerCase());return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]||''])));}
async function importCaptions(file){if(!file)return;const text=await file.text();let rows;if(file.name.endsWith('.json')){const data=JSON.parse(text);rows=Array.isArray(data)?data:Object.entries(data).map(([id,caption])=>({id,caption}));}else if(file.name.endsWith('.csv'))rows=parseCSV(text);else rows=text.split(/^##\s+/m).slice(1).map(c=>({id:c.match(/^([VIC]\d+)/i)?.[1],caption:c.match(/Caption:\s*\r?\n([\s\S]*?)(?=\r?\n\s*\r?\n|$)/i)?.[1]}));let matched=0;for(const row of rows){const item=importGroups.find(x=>x.id===String(row.id||'').toUpperCase());if(item&&typeof row.caption==='string'){item.caption=row.caption.trim();matched++;}}if(!matched)throw new Error('Belum ada ID caption yang cocok.');}
async function commitImport(){captureMapping();if(importGroups.some(x=>!/^[A-Z][A-Z0-9_-]{0,23}$/.test(x.id)||!x.title))throw new Error('Lengkapi ID dan judul yang valid.');if(new Set(importGroups.map(x=>x.id)).size!==importGroups.length)throw new Error('ID dalam impor tidak boleh sama.');let added=0,skipped=0;for(const item of importGroups){if(workspace.posts.some(x=>x.id===item.id)){skipped++;continue;}await api('/api/posts','POST',{...item,mediaIds:item.media.map(x=>x.id)});added++;}await load();state.importStep=3;render();toast(`${added} konten ditambahkan sebagai draft.${skipped?' '+skipped+' ID yang sudah ada dilewati.':''}`);}
root.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled||busy||detailClosePromise)return;const [action,...rest]=target.dataset.action.split(':'),id=rest.join(':');void run(async()=>{
 if(await smart.handle(action,id))return;if(await market.handle(action,id))return;
 if(action==='nav'){navigate(id);return;}if(action==='dismiss-toast'){$('#vs-toast').hidden=true;return;}if(action==='confirm-no'){root.querySelector('#vs-confirm').close();confirmation=null;return;}if(action==='confirm-yes'){const fn=confirmation;confirmation=null;root.querySelector('#vs-confirm').close();await fn?.();return;}if(action==='logout'){if(dirty){ask('Ada perubahan belum disimpan. Tetap keluar?',async()=>{dirty=false;state.modal=null;await api('/api/auth/logout','POST');csrf='';user=null;workspace=null;await authPage();},'Keluar');return;}state.modal=null;await api('/api/auth/logout','POST');csrf='';user=null;workspace=null;await authPage();return;}
 if(action==='expand-caption'){$('.vs-summary-caption').classList.toggle('expanded');return;}if(action==='quick-filter'){state.quick=id;render();return;}if(action==='enter-edit'){await enterEdit();return;}if(action==='edit-schedule'){await enterEdit();$('#edit-date')?.focus();return;}if(action==='detail-summary'){showSummary();return;}if(action==='version-preview'){state.versionId=id;$('#version-comparison').innerHTML=versionComparison();icons();return;}if(action==='version-restore'){restoreVersion(id);return;}if(action==='close-detail'){await closeDetail();return;}if(action==='post-now'){openPostNow(id);return;}if(action==='publish-confirm'){await publishNow();return;}if(action==='more-menu'){state.returnAction='more-menu';state.modal='menu';renderDetail();return;}if(action==='edit'){openEditor(id);return;}if(action==='select'){state.selected=id;slide=0;render();return;}if(action==='day'){state.day=id;state.anchor=id;render();return;}if(action==='clear-day'){state.day=null;render();return;}if(action==='mode'){state.mode=id;state.day=null;render();return;}if(action==='today'){state.anchor=today();state.day=null;render();return;}if(action==='prev-period'||action==='next-period'){const delta=action==='prev-period'?-1:1;if(state.mode==='month'){const d=dateObj(state.anchor.slice(0,7)+'-01');d.setUTCMonth(d.getUTCMonth()+delta);state.anchor=d.toISOString().slice(0,10);}else state.anchor=addDays(state.anchor,delta*7);state.day=null;render();return;}
 if(action==='slide-prev'||action==='slide-next'){const item=(state.view==='editor'||state.modal==='content')&&draft?draft:current();slide=(slide+(action==='slide-next'?1:-1)+item.media.length)%item.media.length;$('#vs-preview').innerHTML=state.modal==='content'&&state.detailMode==='summary'?compactMedia(item):preview(item,!!draft&&(state.view==='editor'||state.modal==='content'));icons();return;}if(action==='up'||action==='down'){readEditor();const from=Number(id),to=from+(action==='up'?-1:1);if(to<0||to>=draft.media.length)return;[draft.media[from],draft.media[to]]=[draft.media[to],draft.media[from]];markDirty();slide=to;renderSlides();$('#vs-preview').innerHTML=preview(draft,true);icons();return;}if(action==='capture-cover'){await captureCover();return;}if(action==='save'){await save(id);return;}
 if(action==='pause'){await mutate('/api/workspace/settings','POST',{paused:!workspace.settings.paused},null,workspace.settings.paused?'Antrean dilanjutkan.':'Seluruh antrean dijeda.');return;}if(action==='cancel'){ask('Batalkan jadwal '+id+'? Konten kembali ke siap tayang.',()=>mutate('/api/posts/'+id+'/cancel','POST',{},'queue','Jadwal dibatalkan.'),'Batalkan jadwal');return;}if(action==='delivery'){state.selected=id;state.view='delivery';slide=0;render();return;}if(action==='retry'){const item=await api('/api/posts/'+id+'/retry','POST',{});await load();openEditor(item.id);toast('Periksa konten dan pilih jadwal baru.');return;}if(action==='reconcile'){await mutate('/api/posts/'+id+'/reconcile','POST',{},'delivery','Status hasil diperiksa melalui Meta.');return;}if(action==='duplicate'){const item=await api('/api/posts/'+id+'/duplicate','POST',{});await load();openEditor(item.id);toast('Salinan dibuat sebagai draft.');return;}
 if(action==='import-again'){state.importStep=1;importGroups=[];render();return;}if(action==='commit-import'){await commitImport();return;}if(action==='ig-connect'){const data=await api('/api/instagram/connect','POST',{});const url=new URL(data.url);if(!['www.instagram.com','instagram.com'].includes(url.hostname)||url.protocol!=='https:')throw new Error('Alamat login Instagram tidak valid.');location.assign(data.url);return;}if(action==='ig-check'){await mutate('/api/instagram/check','POST',{},'settings','Koneksi Instagram aktif.');return;}if(action==='ig-disconnect'){ask('Putuskan Instagram? Publikasi otomatis akan dinonaktifkan.',()=>mutate('/api/instagram/disconnect','POST',{},'settings','Koneksi dilepaskan.'),'Putuskan');return;}
 if(action==='enable-live'){if(!workspace.instagram.connected||!workspace.instagram.configured||!workspace.instagram.publicUrlReady)throw new Error('Siapkan konfigurasi Meta, HTTPS publik, dan koneksi Instagram terlebih dahulu.');ask('Aktifkan publikasi nyata? Konten terjadwal akan diterbitkan saat antrean dilanjutkan.',()=>mutate('/api/workspace/publishing','POST',{enabled:true,confirmation:'AKTIFKAN'},'settings','Publikasi nyata diaktifkan. Periksa antrean sebelum melanjutkan.'),'Aktifkan publikasi nyata');return;}if(action==='disable-live'){await mutate('/api/workspace/publishing','POST',{enabled:false},'settings','Publikasi dinonaktifkan dan antrean dijeda.');return;}
 },target);},{signal:lifetime.signal});
async function init(){try{const params=new URLSearchParams(location.search);inviteToken=params.get('invite')||'';const status=await api('/api/auth/status');if(inviteToken){const invitation=await api('/api/invites/'+encodeURIComponent(inviteToken));await authPage('invite',invitation.email);return;}if(!status.authenticated){await authPage(status.setupRequired?'setup':'login');return;}const session=await api('/api/me');csrf=session.csrf;user=session.user;await load();const legacy=location.hash.slice(1),route=pageIds.includes(legacy)?legacy:pendingRoute;if(pageIds.includes(route))state.view=route;if(pageIds.includes(legacy))options.navigate?.(legacy,{replace:true});render();if(params.has('instagram')){toast(params.get('instagram')==='connected'?'Instagram berhasil dihubungkan.':'Koneksi Instagram belum selesai. Periksa pengaturan dan coba kembali.',params.get('instagram')!=='connected');options.navigate?.('settings',{replace:true});}}catch(e){if(disposed)return;root.innerHTML=`<section class="vs-panel vs-pad vs-stack"><h1>Workspace belum dapat dibuka</h1><p>${esc(e.message)}</p><a class="vs-button" href="/">Coba kembali</a></section>`;}}


function compactMedia(item){const m=item.media[slide]||item.media[0];return`<div class="vs-compact-art">${item.format==='Reel'?`<video class="vs-compact-video" controls playsinline preload="metadata" poster="${esc(item.cover?.url||m?.posterUrl||'')}" aria-label="${esc(item.title)}"><source src="${esc(m?.url)}" type="video/mp4"></video>`:`<img src="${esc(m?.url||'/brand/icon.svg')}" alt="${esc(item.alt||item.title)}">`}</div>${item.format==='Carousel'?`<div class="vs-slidebar">${button('','slide-prev','vs-icon-button','chevron-left','aria-label="Slide sebelumnya"')}<span>Slide ${slide+1} dari ${item.media.length}</span>${button('','slide-next','vs-icon-button','chevron-right','aria-label="Slide berikutnya"')}</div>`:''}`;}
function draftReadiness(){const r=clone(current().readiness);if(!r||!draft)return r;for(const c of r.checks){if(c.id==='caption'){c.ok=!!draft.caption.trim()&&draft.caption.length<=2200;c.detail=c.ok?'Caption terisi dan dalam batas karakter.':'Isi caption dengan maksimal 2.200 karakter.';}if(c.id==='approval'){c.ok=draft.approved===true;c.detail=c.ok?'Media dan caption telah disetujui.':'Tinjau materi dan berikan persetujuan di editor.';}if(c.id==='alt'){c.ok=draft.format==='Reel'||!!String(draft.alt||'').trim();c.detail=draft.format==='Reel'?'Tidak diterapkan untuk Reel.':c.ok?'Deskripsi sudah terisi.':'Tambahkan deskripsi gambar untuk pembaca layar.';}}r.ready=!r.locked&&r.checks.filter(c=>c.required).every(c=>c.ok);r.contentReady=r.checks.filter(c=>['media','caption','approval'].includes(c.id)).every(c=>c.ok);return r;}
function refreshDraftReadiness(){if($('#editor-readiness')&&draft){const open=$('#editor-readiness details')?.open;$('#editor-readiness').innerHTML=readinessHTML(draftReadiness(),{expanded:open});icons();}}
function readinessHTML(report,{expanded=false}={}){if(!report)return'';const required=report.checks.filter(c=>c.required),passed=required.filter(c=>c.ok).length;return`<details class="vs-readiness" ${expanded?'open':''}><summary>${icon(report.ready?'circle-check':'list-checks')}<span>Kesiapan posting <b>${passed}/${required.length}</b></span><span class="vs-status ${report.ready?'ready':'review'}">${report.locked?'Terkunci':report.ready?'Siap dipublikasikan':'Perlu dilengkapi'}</span></summary><div class="vs-readiness-list">${report.checks.map(c=>`<div><span class="vs-readiness-mark ${c.ok?'pass':'wait'}">${icon(c.ok?'check':'minus')}</span><div><b>${esc(c.label)}</b><p>${esc(c.detail)}</p></div>${!c.ok?button(c.action==='settings'?'Pengaturan':'Edit',c.action==='settings'?'nav:settings':'enter-edit','vs-text-button'):''}</div>`).join('')}</div><p class="vs-mini">${esc(report.note)}</p></details>`;}
function detailSummary(item){return`<div class="vs-summary-layout"><section class="vs-summary-media" id="vs-preview"></section><section class="vs-summary-copy"><div class="vs-row"><span class="vs-eyebrow">${esc(item.id)} · ${esc(item.format)}</span>${badge(item)}</div><h2 data-user-content>${esc(item.title)}</h2><div class="vs-summary-meta"><span>${esc(item.category)}</span><span>${esc(item.goal)}</span></div><div class="vs-summary-schedule">${cardTime(item)}${!publishLocked(item)?button('Atur jadwal','edit-schedule','vs-text-button'):''}</div><h3>Caption</h3><div class="vs-summary-caption" data-user-content>${esc(item.caption||'—')}</div>${item.caption.length>220?button('Lihat caption lengkap','expand-caption','vs-text-button'):''}${item.error?`<p class="vs-inline-error">${esc(item.error)}</p>`:''}<p id="detail-error" class="vs-inline-error" role="alert" hidden></p></section></div>${readinessHTML(item.readiness)}`;}
function detailFooter(item){if(state.modal!=='content')return'';return`<footer class="vs-detail-footer">${state.detailMode==='edit'?`<div class="vs-footer-primary">${button('Simpan draft','save:draft','','save')}${button('Simpan jadwal','save:scheduled','vs-primary','calendar-check')}</div><div class="vs-footer-secondary">${button('Kembali ke detail','detail-summary','vs-text-button')}${button('Tandai siap tayang','save:ready','vs-text-button')}${button('Ajukan pemeriksaan','save:review','vs-text-button')}</div>`:publishLocked(item)?`<div class="vs-footer-primary">${button('Buat salinan','duplicate:'+item.id,'','copy')}${item.permalink?`<a class="vs-button vs-primary" href="${esc(item.permalink)}" target="_blank" rel="noopener noreferrer">Lihat di Instagram</a>`:button('Tutup','close-detail')}</div>`:`<div class="vs-footer-primary">${button('Edit konten','enter-edit','','pencil-line')}${button('Post sekarang','post-now:'+item.id,'vs-primary','send')}</div>`}</footer>`;}
async function enterEdit(){if(state.detailMode==='edit'&&draft){$('#edit-caption')?.focus();return;}const item=current();if(publishLocked(item))throw Error('Konten terkunci. Buat salinan untuk mengubah materi.');const response=await api('/api/posts/'+item.id+'/versions');state.versions=response.versions;state.versionId='';draft=clone(item);dirty=false;state.detailMode='edit';smart.reset();renderDetail();}
function showSummary(){if(dirty){ask('Perubahan belum disimpan. Kembali ke detail?',()=>{dirty=false;draft=null;state.detailMode='summary';renderDetail();},'Tinggalkan');return;}draft=null;state.detailMode='summary';renderDetail();}
function versionHistory(){return`<details class="vs-version-history"><summary>${icon('history')}Riwayat versi konten</summary><p class="vs-mini">Versi tersimpan mulai tersedia sejak fitur ini diaktifkan. Pemulihan kembali ke draft dan membatalkan jadwal serta persetujuan.</p><div class="vs-version-list">${state.versions.map(v=>`<div><span><b>Versi ${v.revision}</b><small>${stamp(v.created_at)} · ${v.reason==='ai'?'AI':v.reason==='restore'?'Pemulihan':'Edit'}</small></span>${button('Bandingkan','version-preview:'+v.id)}</div>`).join('')}</div><div id="version-comparison"></div></details>`;}
function versionComparison(){const v=state.versions.find(v=>v.id===state.versionId);if(!v)return'';return`<div class="vs-compare-grid"><article><h3>Versi saat ini</h3><p data-user-content>${esc($('#edit-caption')?.value||current().caption)}</p></article><article><h3>Versi tersimpan ${v.revision}</h3><p data-user-content>${esc(v.body.caption||'')}</p></article></div><p class="vs-mini">Pemulihan mencakup judul, caption, deskripsi, media, dan kategori pada versi ini.</p>${button('Pulihkan versi ini','version-restore:'+v.id,'','rotate-ccw')}`;}
function restoreVersion(id){const v=state.versions.find(v=>v.id===id);if(!v)return;ask('Pulihkan versi '+v.revision+'? Materi kembali ke draft; jadwal dan persetujuan dibatalkan.',async()=>{const saved=await api('/api/posts/'+current().id+'/restore','POST',{versionId:id,revision:current().revision});dirty=false;await load();state.selected=saved.id;draft=null;state.detailMode='summary';render();toast('Versi dipulihkan sebagai draft.');},'Pulihkan');}

function publishLocked(item){return ['published','processing','uncertain'].includes(item.status)||!!item.mediaId||!!item.job?.publishRequested;}
function cardTime(item){if(item.status==='published'&&item.publishedAt)return`${icon('check-check')}<time datetime="${esc(item.publishedAt)}">${stamp(item.publishedAt)}</time>`;if(item.status==='processing')return`${icon('loader-circle')}<span>Posting sedang diproses</span>`;if(item.status==='scheduled'&&item.scheduleAt)return`${icon('calendar-clock')}<time datetime="${esc(item.scheduleAt)}">${stamp(item.scheduleAt)}</time>`;return`${icon('calendar')}<span>Belum dijadwalkan</span>`;}
function bottomNavigation(){const primary=['library','calendar','queue','assistant'];return[['library','layout-grid','Pustaka'],['calendar','calendar-days','Kalender'],['queue','list-ordered','Antrean'],['assistant','sparkles','Asisten'],['more','menu','Menu']].map(([id,ic,label])=>`<button type="button" data-action="${id==='more'?'more-menu':'nav:'+id}" ${state.view===id||id==='more'&&!primary.includes(state.view)?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='more'&&count('review')?'<b class="vs-mobile-dot" aria-label="Perlu diperiksa"></b>':''}</button>`).join('');}
function moreMenu(){return`${menuGridHTML({view:state.view,reviewCount:count('review'),icon})}<div class="vs-menu-preferences"><span>Bahasa</span>${languagePicker()}</div>`;}
function openPostNow(id){state.returnAction='post-now:'+id;state.selected=id;draft=null;dirty=false;slide=0;state.modal='publish';renderDetail();}
function publishContent(item){const ready=workspace.instagram.configured&&workspace.instagram.connected&&workspace.instagram.publicUrlReady&&workspace.settings.publishingEnabled;return`<div class="vs-columns"><section class="vs-panel vs-pad vs-stack"><span class="vs-eyebrow">INSTAGRAM ${workspace.instagram.username?'· @'+esc(workspace.instagram.username):''}</span><h2 data-user-content>${esc(item.title)}</h2>${badge(item)}${publishLocked(item)?`<div class="vs-banner ${item.status==='published'?'success':''}"><span>${item.status==='published'?'Konten telah terbit.':item.status==='processing'?'Posting sedang diproses':'Permintaan publikasi pernah dikirim. Periksa hasil sebelum mencoba lagi.'}</span></div>${item.permalink?`<a class="vs-button" href="${esc(item.permalink)}" target="_blank" rel="noopener noreferrer">Lihat di Instagram</a>`:''}${item.error?`<p class="vs-inline-error">${esc(item.error)}</p>`:''}`:`<h3>Periksa sebelum publikasi</h3><p class="vs-sub">Publikasi memakai versi tersimpan; periksa kembali media, caption, dan akun tujuan.</p>${item.status==='scheduled'?`<div class="vs-item-lock"><p>Post sekarang menggantikan jadwal konten ini. Jadwal konten lain tetap.</p><time datetime="${esc(item.scheduleAt)}">${stamp(item.scheduleAt)}</time></div>`:''}${workspace.settings.paused&&ready?'<p class="vs-mini">Posting manual dapat berjalan saat antrean dijeda.</p>':''}${!ready?`<div class="vs-banner"><span><b>Koneksi belum siap</b><br>Hubungkan Instagram dan aktifkan publikasi di Pengaturan untuk memublikasikan.</span></div>${button('Periksa koneksi di Pengaturan','nav:settings')}`:''}${!item.caption.trim()?'<p class="vs-inline-error">Konten belum memiliki caption.</p>':''}<label class="vs-check"><input id="publish-approved" type="checkbox"><span>Media dan caption sudah diperiksa.<br><span class="vs-mini">Termasuk cover, urutan slide, harga, dan informasi penawaran.</span></span></label><p id="publish-error" class="vs-inline-error" role="alert" hidden></p><div class="vs-actions">${button('Publikasikan sekarang','publish-confirm','vs-primary','send',`disabled data-ready="${ready&&!!item.caption.trim()}"`)}${button('Ubah konten','edit:'+item.id)}</div><p class="vs-mini">Tidak ada materi yang akan diterbitkan sebelum kamu menekan Publikasikan sekarang.</p>`}</section><aside class="vs-panel vs-preview" id="vs-preview"></aside></div>`;}
let detailClosePromise=null;
function positionMenu(dialog=root.querySelector('.vs-menu-dialog')){if(!dialog)return;const nav=root.querySelector('.vs-bottom-nav'),height=nav?.getBoundingClientRect().height||0;dialog.style.setProperty('--vs-menu-nav-height',height+'px');dialog.style.setProperty('--vs-menu-bottom',(height?height+10:24)+'px');}
window.addEventListener('resize',()=>positionMenu(),{signal:lifetime.signal});
function renderDetail(){
 const old=root.querySelector('#vs-detail');
 const dialog=old||document.createElement('dialog');dialog.id='vs-detail';dialog.className='vs-detail-dialog'+(state.modal==='menu'?' vs-menu-dialog':'');dialog.setAttribute('aria-labelledby','vs-detail-title');dialog.dataset.mode=state.modal==='content'?state.detailMode:state.modal;
 if(state.modal==='menu')positionMenu(dialog);
 const item=current(),title=state.modal==='menu'?'Menu':state.modal==='publish'?'Tinjau & post sekarang':state.detailMode==='edit'?'Edit konten':'Detail konten';
 dialog.innerHTML=`<header class="vs-detail-header"><div><span class="vs-eyebrow">VAYORA SOCIAL STUDIO</span><h2 id="vs-detail-title">${title}</h2></div><div class="vs-detail-tools">${state.modal==='menu'?'':languagePicker()}${button('','close-detail','vs-icon-button','x','aria-label="Tutup detail"')}</div></header><div class="vs-detail-body">${state.modal==='menu'?moreMenu():state.modal==='publish'?publishContent(item):state.detailMode==='edit'&&draft?editor():detailSummary(item)}</div>${detailFooter(item)}`;
 if(!old){dialog.dataset.phase=matchMedia('(prefers-reduced-motion: reduce)').matches?'open':'entering';root.append(dialog);dialog.showModal();requestAnimationFrame(()=>requestAnimationFrame(()=>{if(dialog.isConnected&&dialog.dataset.phase==='entering')dialog.dataset.phase='open';}));}else{dialog.dataset.phase='open';dialog.scrollTop=0;}
 if(state.modal!=='menu'&&$('#vs-preview'))$('#vs-preview').innerHTML=state.modal==='content'&&state.detailMode==='summary'?compactMedia(item):preview(draft||item,!!draft&&state.modal==='content');
 if(state.modal==='content'&&state.detailMode==='edit'&&draft){renderSlides();bindEditor();}
 $('#publish-approved')?.addEventListener('change',e=>{$('[data-action="publish-confirm"]').disabled=!e.target.checked||$('[data-action="publish-confirm"]').dataset.ready!=='true';});
 if(!old)dialog.addEventListener('cancel',e=>{e.preventDefault();if(!busy)closeDetail();});
 if(!old)dialog.addEventListener('click',e=>{if(e.target===dialog&&!busy){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail();}});
 icons();localize(dialog);
 const focus=dialog.querySelector('.vs-detail-header button');focus?.focus({preventScroll:true});
}
function closeDetail(force=false){
 if(detailClosePromise)return detailClosePromise;
 if(dirty&&!force){ask('Perubahan belum disimpan. Tutup detail ini?',()=>closeDetail(true),'Tinggalkan');return Promise.resolve();}
 const id=state.selected,dialog=root.querySelector('#vs-detail'),scroll=window.scrollY;
 detailClosePromise=(async()=>{
   if(dialog?.open&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
     dialog.dataset.phase='closing';
     await new Promise(resolve=>{let timer;const finish=()=>{clearTimeout(timer);dialog.removeEventListener('transitionend',ended);resolve();};const ended=e=>{if(e.target===dialog&&e.propertyName==='opacity')finish();};dialog.addEventListener('transitionend',ended);timer=setTimeout(finish,220);});
   }
   dirty=false;draft=null;state.modal=null;dialog?.close();dialog?.remove();render();window.scrollTo({top:scroll,behavior:'instant'});root.querySelector(`[data-action="${state.returnAction||'edit:'+id}"]`)?.focus({preventScroll:true});
 })().finally(()=>{detailClosePromise=null;});
 return detailClosePromise;
}
async function publishNow(){const item=current();if(!$('#publish-approved')?.checked)throw Error('Periksa media dan caption, lalu konfirmasi Post sekarang.');await api('/api/posts/'+item.id+'/publish-now','POST',{revision:item.revision,approved:true,confirmation:'PUBLISH_NOW'});await load();state.selected=item.id;state.modal='publish';render();toast('Publikasi dimulai. Status hasil akan diperbarui di sini.');pollPublication(item.id);}
const publicationTimers=new Map();
function pollPublication(id){if(publicationTimers.has(id)||!workspace)return;const job={started:Date.now(),busy:false,timer:null};job.timer=setInterval(async()=>{if(job.busy)return;if(!workspace||Date.now()-job.started>8*60000){clearInterval(job.timer);publicationTimers.delete(id);return;}job.busy=true;try{const post=await api('/api/posts/'+id);if(!workspace)return;const before=workspace.posts.find(p=>p.id===id);workspace.posts=workspace.posts.map(p=>p.id===id?post:p);if(post.status!=='processing'){clearInterval(job.timer);publicationTimers.delete(id);}if(post.status!==before?.status){if(!detailClosePromise&&((!state.modal&&['library','queue','calendar','history'].includes(state.view))||(['publish','content'].includes(state.modal)&&!draft&&state.selected===id)))render();if(post.status==='published')toast('Konten telah terbit.');}}catch(e){clearInterval(job.timer);publicationTimers.delete(id);toast(e.message,true);}finally{job.busy=false;}},2000);publicationTimers.set(id,job);}

const languageObserver=observeLanguage(root);
root.addEventListener('change',event=>{if(event.target.matches('[data-language]')){if(draft&&$('#edit-caption'))readEditor();setLanguage(event.target.value);document.querySelectorAll('[data-language]').forEach(el=>el.value=getLanguage());localize(root);if(workspace){for(const card of root.querySelectorAll('[data-post-id]')){const post=workspace.posts.find(p=>p.id===card.dataset.postId);if(post)card.querySelector('.vs-card-schedule').innerHTML=cardTime(post);}for(const time of root.querySelectorAll('time[datetime]'))time.textContent=stamp(time.dateTime);icons();}}},{signal:lifetime.signal});
const smart=createSmartTools({api,$,esc,button,icons,toast,readEditor,markDirty,render,run,reload:load,openEditor,openCaption,getDraft:()=>draft,getWorkspace:()=>workspace,getUser:()=>user});
const market=createMarketingUI({api,$,esc,button,icons,toast,ask,parseCSV,stamp,render,run,workspace:()=>workspace,user:()=>user});
function syncRoute(view){pendingRoute=view;if(disposed||!workspace||!pageIds.includes(view)||view===state.view)return;if(busy){options.navigate?.(state.view,{replace:true});return;}if(dirty)options.navigate?.(state.view,{replace:true});navigate(view);}
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(pageIds.includes(view))syncRoute(view);},{signal:lifetime.signal});
void init();
return{syncRoute,dispose(){disposed=true;lifetime.abort();languageObserver.disconnect();for(const job of publicationTimers.values())clearInterval(job.timer);root.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());root.innerHTML='';}};
}
